python - <<'PY'
import inspect
from sqlglot import parse_one, exp
from sqlglot.errors import ErrorLevel
import sqlframe.standalone.functions as SF
ignore_funcs = {'array_size','to_char','ltrim','rtrim'}
for name, func in inspect.getmembers(SF, inspect.isfunction):
    if 'invoke_anonymous_function' in inspect.getsource(func) and name not in ignore_funcs:
        parsed = parse_one(f'{name}()', read='spark', error_level=ErrorLevel.IGNORE)
        if not isinstance(parsed, exp.Anonymous):
            print(name, type(parsed).__name__, getattr(type(parsed), 'arg_types', None))
PY

